mapper.select:
SELECT	COUNT(*) AS CNT
FROM	UI_CO
WHERE	CONM	= #{coNm}

AND		COCD != #{coCd}

SELECT	COUNT(*) AS CNT
FROM	UI_CO
WHERE	COCD	= #{coCd}

mapper.update:
UPDATE	UI_CO 
SET		CONM = #{coNm}
WHERE	COCD = #{coCd}

mapper.select:
SELECT A.COCD AS coCd, A.CONM AS coNm, B.BUSICD AS busiCd, B.BUSINM AS busiNm FROM UI_CO A, UI_BUSI B WHERE A.COCD = B.COCD
AND A.COCD = #{coCd}
ORDER BY A.COCD, B.BUSICD

SELECT	COUNT(*) AS CNT
FROM	UI_BUSI
WHERE	BUSINM	= #{busiNm}

AND		BUSICD != #{busiCd}

SELECT	COUNT(*) AS CNT
FROM	UI_BUSI
WHERE	BUSICD	= #{busiCd}

mapper.update:
UPDATE	UI_BUSI 
SET		BUSINM 	= #{busiNm},
		COCD	= #{coCd}
WHERE	BUSICD 	= #{busiCd}

mapper.select:
SELECT A.COCD AS coCd, A.CONM AS coNm, B.GENERALCD AS generalCd, B.GENERALNM AS generalNm FROM UI_CO A, UI_GENERAL B WHERE A.COCD = B.COCD
AND A.COCD = #{coCd}
ORDER BY A.COCD, B.GENERALCD

SELECT	COUNT(*) AS CNT
FROM	UI_GENERAL
WHERE	GENERALNM	= #{generalNm}

AND		GENERALCD != #{generalCd}

SELECT	COUNT(*) AS CNT
FROM	UI_GENERAL
WHERE	GENERALCD	= #{generalCd}

mapper.update:
UPDATE	UI_GENERAL 
SET		GENERALNM 	= #{generalNm},
		COCD		= #{coCd}
WHERE	GENERALCD 	= #{generalCd}

mapper.select:
SELECT A.COCD AS coCd, A.CONM AS coNm, B.DEPTCD AS deptCd, B.DEPTNM AS deptNm, B.PDEPTCD AS pDeptCd, C.DEPTNM AS pDeptNm FROM UI_CO A, UI_DEPT B LEFT OUTER JOIN UI_DEPT C ON B.PDEPTCD = C.DEPTCD WHERE A.COCD = B.COCD
AND A.COCD = #{coCd}
ORDER BY A.COCD, B.DEPTCD

SELECT	COUNT(*) AS CNT
FROM	UI_DEPT
WHERE	DEPTNM	= #{deptNm}

AND		DEPTCD != #{deptCd}

SELECT	COUNT(*) AS CNT
FROM	UI_DEPT
WHERE	DEPTCD	= #{deptCd}

mapper.update:
UPDATE	UI_DEPT 
SET		DEPTNM 		= #{deptNm},
		PDEPTCD		= #{pDeptCd},
		COCD		= #{coCd}
WHERE	DEPTCD 		= #{deptCd}

